const firebaseApp = global.get('firebaseApp');
const firebaseDatabase = global.get('firebaseDatabase');
const crypto = global.get('crypto');
const serviceAccount = global.get('serviceAccount');

if (!firebaseApp || typeof firebaseApp.initializeApp !== 'function') {
    node.error('global.get(\"firebaseApp\") không hợp lệ (kiểu=' + typeof firebaseApp + '). Kiểm tra dòng firebaseApp: require(\'firebase-admin/app\') trong settings.js, và nhớ restart Node-RED chưa.');
    return null;
}
if (!firebaseDatabase || typeof firebaseDatabase.getDatabase !== 'function') {
    node.error('global.get(\"firebaseDatabase\") không hợp lệ. Kiểm tra dòng firebaseDatabase: require(\'firebase-admin/database\') trong settings.js.');
    return null;
}
if (!crypto || typeof crypto.randomBytes !== 'function') {
    node.error('global.get(\"crypto\") không hợp lệ. Kiểm tra dòng crypto: require(\'crypto\') trong settings.js.');
    return null;
}
if (!serviceAccount || typeof serviceAccount !== 'object') {
    node.error('global.get(\"serviceAccount\") không hợp lệ (kiểu=' + typeof serviceAccount + '). Kiểm tra dòng serviceAccount: require(...) trong settings.js có đúng đường dẫn file serviceAccountKey.json không.');
    return null;
}

let db = global.get('db');

if (!db) {
    const { initializeApp, cert, getApps } = firebaseApp;
    const { getDatabase } = firebaseDatabase;

    if (getApps().length === 0) {
        try {
            initializeApp({
                credential: cert(serviceAccount),
                databaseURL: 'https://YOUR_PROJECT_ID-default-rtdb.asia-southeast1.firebasedatabase.app'
            });
        } catch (err) {
            node.error('initializeApp thất bại - kiểm tra lại databaseURL và nội dung serviceAccountKey.json. Lỗi gốc: ' + err.message);
            return null;
        }
    }

    try {
        db = getDatabase();
    } catch (err) {
        node.error('getDatabase() thất bại - kiểm tra lại databaseURL. Lỗi gốc: ' + err.message);
        return null;
    }
    global.set('db', db);
}

try {
    const usernameSnap = await db.ref('users').orderByChild('username').equalTo('admin').once('value');
    if (!usernameSnap.exists()) {
        const salt = crypto.randomBytes(16).toString('hex');
        const hash = crypto.scryptSync('admin123', salt, 64).toString('hex');

        const newUserRef = db.ref('users').push();
        await newUserRef.set({
            username: 'admin',
            email: 'admin@hgm.local',
            password_hash: hash,
            password_salt: salt,
            role: 'admin',
            created_at: new Date().toISOString()
        });
        node.warn('Đã tạo tài khoản admin mặc định: admin / admin123 - nhớ đổi mật khẩu sau khi test xong nhé!');
    }

    const statusSnap = await db.ref('door_status').once('value');
    if (!statusSnap.exists()) {
        await db.ref('door_status').set({
            state: 'locked',
            method: null,
            user: null,
            lockdown: false,
            updatedAt: new Date().toISOString()
        });
    }
} catch (err) {
    node.error('Kết nối được Firebase nhưng đọc/ghi thất bại - kiểm tra Realtime Database Rules và databaseURL. Lỗi gốc: ' + err.message);
}

return null;

// msg.payload nhận vào dạng: { type: 'fingerprint'|'rfid'|'ble'|'pin', value: '...' }
const db = global.get('db');
const body = msg.payload || {};
const safeKey = (s) => String(s).replace(/[.#$\[\]\/]/g, '_');

node.warn('[verify] nhận yêu cầu: type=' + body.type + ' value=' + body.value);

const lookupSnap = await db.ref(`credential_lookup/${body.type}/${safeKey(body.value)}`).once('value');
if (!lookupSnap.exists()) {
    node.warn('[verify] DENY - không tìm thấy credential_lookup/' + body.type + '/' + safeKey(body.value));
    return [{ payload: { cmd: 'DENY' } }, null];
}

const credId = lookupSnap.val();
const credSnap = await db.ref('credentials/' + credId).once('value');
const cred = credSnap.val();
if (!cred) {
    node.warn('[verify] DENY - lookup có nhưng credentials/' + credId + ' không tồn tại (dữ liệu bị lệch)');
    return [{ payload: { cmd: 'DENY' } }, null];
}

const userSnap = await db.ref('users/' + cred.user_id).once('value');
const user = userSnap.val();
if (!user) {
    node.warn('[verify] DENY - credential có nhưng user_id=' + cred.user_id + ' không tồn tại');
    return [{ payload: { cmd: 'DENY' } }, null];
}

const now = new Date().toISOString();
await db.ref('access_logs').push({
    user_id: cred.user_id,
    username: user.username,
    method: body.type,
    time: now
});

const statusSnap = await db.ref('door_status').once('value');
const prevStatus = statusSnap.val() || {};
await db.ref('door_status').set({
    state: 'unlocked',
    method: body.type,
    user: user.username,
    lockdown: prevStatus.lockdown || false,
    updatedAt: now
});

node.warn('[verify] GRANT - mở cửa cho ' + user.username + ' bằng ' + body.type);

const resultMsg = { payload: { cmd: 'GRANT' } };
const sheetsMsg = { payload: { time: now, user: user.username, method: body.type } };
return [resultMsg, sheetsMsg];

const TELEGRAM_TOKEN = 'YOUR_BOT_TOKEN';
const CHAT_ID = 'YOUR_CHAT_ID';

const text = 'CẢNH BÁO HGM: phát hiện bất thường tại cửa (' + (msg.payload.reason || 'không rõ') + ') lúc ' + new Date().toLocaleString('vi-VN');

msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.url = 'https://api.telegram.org/bot' + TELEGRAM_TOKEN + '/sendMessage';
msg.payload = { chat_id: CHAT_ID, text: text };
return msg;

const db = global.get('db');
const authHeader = (msg.req && msg.req.headers['authorization']) || '';
const token = authHeader.replace('Bearer ', '').trim();

msg.authUser = null;
msg.authError = null;

if (!token) {
    msg.authError = 'Thiếu token đăng nhập';
    return msg;
}

const sessionSnap = await db.ref('sessions/' + token).once('value');
const session = sessionSnap.val();

if (!session || new Date(session.expires_at) < new Date()) {
    msg.authError = 'Token không hợp lệ hoặc đã hết hạn';
    return msg;
}

const userSnap = await db.ref('users/' + session.user_id).once('value');
const user = userSnap.val();

if (!user) {
    msg.authError = 'Tài khoản không còn tồn tại';
    return msg;
}

msg.authUser = { id: session.user_id, username: user.username, email: user.email, role: user.role };
return msg;

const db = global.get('db');
const crypto = global.get('crypto');
const body = msg.payload || {};

if (!body.username || !body.email || !body.password) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Thiếu username/email/password' };
    return msg;
}
if (body.password.length < 6) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Mật khẩu tối thiểu 6 ký tự' };
    return msg;
}

const usernameSnap = await db.ref('users').orderByChild('username').equalTo(body.username).once('value');
if (usernameSnap.exists()) {
    msg.statusCode = 409;
    msg.payload = { ok: false, error: 'Username đã tồn tại' };
    return msg;
}
const emailSnap = await db.ref('users').orderByChild('email').equalTo(body.email).once('value');
if (emailSnap.exists()) {
    msg.statusCode = 409;
    msg.payload = { ok: false, error: 'Email đã tồn tại' };
    return msg;
}

const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.scryptSync(body.password, salt, 64).toString('hex');

const newUserRef = db.ref('users').push();
await newUserRef.set({
    username: body.username,
    email: body.email,
    password_hash: hash,
    password_salt: salt,
    role: 'member',
    created_at: new Date().toISOString()
});

msg.payload = { ok: true, message: 'Đăng ký thành công, hãy đăng nhập' };
return msg;

const db = global.get('db');
const crypto = global.get('crypto');
const body = msg.payload || {};

const snap = await db.ref('users').orderByChild('username').equalTo(body.username).once('value');
if (!snap.exists()) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: 'Sai username hoặc mật khẩu' };
    return msg;
}

let userId, user;
snap.forEach((child) => { userId = child.key; user = child.val(); });

const hash = crypto.scryptSync(body.password || '', user.password_salt, 64).toString('hex');
if (hash !== user.password_hash) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: 'Sai username hoặc mật khẩu' };
    return msg;
}

const token = crypto.randomBytes(32).toString('hex');
const expires = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();

await db.ref('sessions/' + token).set({ user_id: userId, expires_at: expires });

msg.payload = {
    ok: true,
    token: token,
    user: { id: userId, username: user.username, email: user.email, role: user.role }
};
return msg;

const db = global.get('db');
const authHeader = (msg.req && msg.req.headers['authorization']) || '';
const token = authHeader.replace('Bearer ', '').trim();
if (token) await db.ref('sessions/' + token).remove();
msg.payload = { ok: true };
return msg;

const db = global.get('db');
const crypto = global.get('crypto');
const email = (msg.payload || {}).email;

const snap = await db.ref('users').orderByChild('email').equalTo(email).once('value');
if (snap.exists()) {
    let userId;
    snap.forEach((child) => { userId = child.key; });

    const token = crypto.randomBytes(24).toString('hex');
    const expires = new Date(Date.now() + 15 * 60 * 1000).toISOString();
    await db.ref('password_resets/' + token).set({ user_id: userId, expires_at: expires });
    // Local/dev: chưa nối SMTP thật, nên in link ra log Node-RED để test.
    node.warn('[DEV] Link đặt lại mật khẩu cho ' + email + ': reset-password.html?token=' + token);
}

msg.payload = { ok: true, message: 'Nếu email tồn tại trong hệ thống, hướng dẫn đặt lại mật khẩu đã được gửi' };
return msg;

const db = global.get('db');
const crypto = global.get('crypto');
const body = msg.payload || {};

const snap = await db.ref('password_resets/' + body.token).once('value');
const record = snap.val();

if (!record || new Date(record.expires_at) < new Date()) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Token không hợp lệ hoặc đã hết hạn' };
    return msg;
}
if (!body.newPassword || body.newPassword.length < 6) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Mật khẩu mới tối thiểu 6 ký tự' };
    return msg;
}

const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.scryptSync(body.newPassword, salt, 64).toString('hex');

await db.ref('users/' + record.user_id).update({ password_hash: hash, password_salt: salt });
await db.ref('password_resets/' + body.token).remove();

// Đăng xuất tất cả session cũ của người này
const sessSnap = await db.ref('sessions').orderByChild('user_id').equalTo(record.user_id).once('value');
const updates = {};
sessSnap.forEach((child) => { updates[child.key] = null; });
if (Object.keys(updates).length) await db.ref('sessions').update(updates);

msg.payload = { ok: true, message: 'Đặt lại mật khẩu thành công, hãy đăng nhập lại' };
return msg;

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
const db = global.get('db');
const snap = await db.ref('door_status').once('value');
msg.payload = snap.val() || {};
return msg;

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
const db = global.get('db');
const limit = parseInt(msg.req.query.limit) || 20;

// access_logs dùng push key (theo thời gian) nên limitToLast lấy được N bản ghi gần nhất
const snap = await db.ref('access_logs').orderByKey().limitToLast(limit).once('value');
const rows = [];
snap.forEach((child) => {
    const v = child.val();
    rows.unshift({ time: v.time, user: v.username, method: v.method });
});
msg.payload = rows;
return msg;

if (msg.authError) {
    const errMsg = { statusCode: 401, payload: { ok: false, error: msg.authError }, res: msg.res };
    return [null, errMsg];
}

const db = global.get('db');
const now = new Date().toISOString();

await db.ref('access_logs').push({
    user_id: msg.authUser.id,
    username: msg.authUser.username,
    method: 'remote_web',
    time: now
});

const statusSnap = await db.ref('door_status').once('value');
const prevStatus = statusSnap.val() || {};
await db.ref('door_status').set({
    state: 'unlocked',
    method: 'remote_web',
    user: msg.authUser.username,
    lockdown: prevStatus.lockdown || false,
    updatedAt: now
});

