const respMsg = { payload: { ok: true, message: 'Đã gửi lệnh mở cửa' }, res: msg.res };
return [cmdMsg, respMsg];

if (msg.authError) {
    const errMsg = { statusCode: 401, payload: { ok: false, error: msg.authError }, res: msg.res };
    return [null, errMsg];
}

const db = global.get('db');
const enable = !!(msg.payload && msg.payload.enable);

const statusSnap = await db.ref('door_status').once('value');
const status = statusSnap.val() || {};
status.lockdown = enable;
status.updatedAt = new Date().toISOString();
await db.ref('door_status').set(status);

const cmdMsg = { payload: { cmd: enable ? 'LOCKDOWN_ON' : 'LOCKDOWN_OFF' } };
const respMsg = { payload: { ok: true, lockdown: enable }, res: msg.res };
return [cmdMsg, respMsg];

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
if (msg.authUser.role !== 'admin') {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: 'Chỉ admin được phép' };
    return msg;
}
