    return msg;
}
const db = global.get('db');
const userId = msg.req.params.id;
const snap = await db.ref('credentials').orderByChild('user_id').equalTo(userId).once('value');
const creds = [];
snap.forEach((child) => {
    const v = child.val();
    creds.push({ id: child.key, type: v.type, credential_value: v.credential_value, label: v.label, created_at: v.created_at });
});
msg.payload = creds;
return msg;

if (msg.authError) {
