    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
if (msg.authUser.role !== 'admin') {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: 'Chỉ admin được phép' };
    return msg;
}

const db = global.get('db');
const userId = msg.req.params.id;
const body = msg.payload || {};

if (!userId || userId === 'undefined' || userId === 'NaN') {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'ID người dùng không hợp lệ: "' + userId + '"' };
    return msg;
}

const userSnap = await db.ref('users/' + userId).once('value');
if (!userSnap.exists()) {
    msg.statusCode = 404;
    msg.payload = { ok: false, error: 'Không tìm thấy người dùng với id: ' + userId };
    return msg;
}

if (!body.type || !body.value) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Thiếu type/value' };
    return msg;
}

const safeKey = (s) => String(s).replace(/[.#$\[\]\/]/g, '_');

// Mỗi giá trị (VD 1 thẻ RFID, 1 vân tay) chỉ được gán cho ĐÚNG 1 người - chặn trùng lặp
const existingLookup = await db.ref(`credential_lookup/${body.type}/${safeKey(body.value)}`).once('value');
if (existingLookup.exists()) {
    msg.statusCode = 409;
    msg.payload = { ok: false, error: 'Giá trị này đã được gán rồi (trùng ' + body.type + ': "' + body.value + '"). Xóa bản ghi cũ trước nếu muốn gán lại cho người khác.' };
    return msg;
}

const credRef = db.ref('credentials').push();
const created_at = new Date().toISOString();

await credRef.set({
    user_id: userId,
    type: body.type,
    credential_value: body.value,
    label: body.label || '',
    created_at: created_at
});
await db.ref(`credential_lookup/${body.type}/${safeKey(body.value)}`).set(credRef.key);

msg.payload = { ok: true, message: 'Đã thêm thông tin xác thực' };
return msg;

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
if (msg.authUser.role !== 'admin') {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: 'Chỉ admin được phép' };
    return msg;
}

const db = global.get('db');
const credId = msg.req.params.id;
const snap = await db.ref('credentials/' + credId).once('value');
const cred = snap.val();

if (cred) {
    const safeKey = (s) => String(s).replace(/[.#$\[\]\/]/g, '_');
    await db.ref('credentials/' + credId).remove();
    await db.ref(`credential_lookup/${cred.type}/${safeKey(cred.credential_value)}`).remove();
}

msg.payload = { ok: true };
return msg;

if (msg.authError) {
    const errMsg = { statusCode: 401, payload: { ok: false, error: msg.authError }, res: msg.res };
    return [null, errMsg];
}

const db = global.get('db');
const now = new Date().toISOString();
await db.ref('access_logs').push({
    user_id: msg.authUser.id,
    username: msg.authUser.username,
    method: 'remote_lock',
    time: now
});

const statusSnap = await db.ref('door_status').once('value');
const prevStatus = statusSnap.val() || {};
await db.ref('door_status').set({
    state: 'locked',
    method: 'remote_lock',
    user: msg.authUser.username,
    lockdown: prevStatus.lockdown || false,
    updatedAt: now
});

const cmdMsg = { payload: { cmd: 'LOCK' } };
const respMsg = { payload: { ok: true, message: 'Đã gửi lệnh đóng cửa' }, res: msg.res };
return [cmdMsg, respMsg];
